package com.acme.learning.certificates;

import java.util.List;

/**
 * Blocks certificate issuance until every mandatory lesson is complete.
 */
public class CompletionCertificateGuard {

    private final LessonProgressRepository progress;
    private final CourseRepository courses;

    public CompletionCertificateGuard(LessonProgressRepository progress, CourseRepository courses) {
        this.progress = progress;
        this.courses = courses;
    }

    public void assertComplete(String learnerId, String courseId) {
        List<String> mandatory = courses.require(courseId).getMandatoryLessonIds();
        for (String lessonId : mandatory) {
            if (!progress.isCompleted(learnerId, lessonId)) {
                throw new IncompleteLessonException(learnerId, courseId, lessonId);
            }
        }
    }
}

class IncompleteLessonException extends RuntimeException {
    public IncompleteLessonException(String learner, String course, String lesson) {
        super("Learner " + learner + " has not completed lesson " + lesson + " of course " + course);
    }
}

