package com.acme.learning.progress;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * Computes progress percentage for a learner in a course.
 */
public class ProgressPercentageCalculator {

    private final LessonProgressRepository progress;
    private final CourseRepository courses;

    public ProgressPercentageCalculator(LessonProgressRepository progress, CourseRepository courses) {
        this.progress = progress;
        this.courses = courses;
    }

    public BigDecimal percentage(String learnerId, String courseId) {
        int total = courses.require(courseId).getLessonCount();
        if (total == 0) {
            return BigDecimal.ZERO;
        }
        int done = progress.completedCount(learnerId, courseId);
        return BigDecimal.valueOf(done * 100.0 / total).setScale(2, RoundingMode.HALF_UP);
    }
}

