package com.acme.learning.enrolment;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/**
 * Enrolment endpoint: prerequisite check, persist enrolment, unlock first module.
 */
@RestController
public class EnrolmentController {

    private final PrerequisiteChecker prerequisites;
    private final EnrolmentRepository enrolments;
    private final ModuleAccessService modules;

    public EnrolmentController(PrerequisiteChecker prerequisites, EnrolmentRepository enrolments, ModuleAccessService modules) {
        this.prerequisites = prerequisites;
        this.enrolments = enrolments;
        this.modules = modules;
    }

    @PostMapping("/enrolments")
    public EnrolmentView enrol(@RequestBody EnrolmentRequest req) {
        prerequisites.assertEligible(req.getLearnerId(), req.getCourseId());
        Enrolment e = enrolments.save(Enrolment.open(req.getLearnerId(), req.getCourseId()));
        modules.unlockFirstModule(req.getLearnerId(), req.getCourseId());
        return EnrolmentView.from(e);
    }
}

