import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * Returns the lesson and playback position where the learner last stopped.
 */
@RestController
public class ResumeController {

    private final LessonProgressRepository progress;

    public ResumeController(LessonProgressRepository progress) {
        this.progress = progress;
    }

    @GetMapping("/courses/resume")
    public ResumeView resume(@RequestParam String learnerId, @RequestParam String courseId) {
        List<LessonProgress> ordered = progress.orderedByLastInteraction(learnerId, courseId);
        if (ordered.isEmpty()) {
            throw new NoResumePointException(learnerId, courseId);
        }
        LessonProgress last = ordered.get(0);
        return new ResumeView(last.getLessonId(), last.getLastPositionSeconds(), last.getLastInteractionAt());
    }
}

