package com.acme.learning.instructor;

import java.time.Instant;

/**
 * Publishes a lesson and notifies enrolled learners.
 */
public class LessonPublishService {

    private final LessonRepository lessons;
    private final EnrolmentRepository enrolments;
    private final NotificationGateway notifier;

    public LessonPublishService(LessonRepository lessons, EnrolmentRepository enrolments, NotificationGateway notifier) {
        this.lessons = lessons;
        this.enrolments = enrolments;
        this.notifier = notifier;
    }

    public Lesson publish(String courseId, LessonDraft draft, String instructorId) {
        if (!instructorId.equals(lessons.courseInstructor(courseId))) {
            throw new IllegalStateException("Only the course instructor may publish");
        }
        Lesson lesson = Lesson.published(courseId, draft, Instant.now());
        lessons.save(lesson);
        for (String learnerId : enrolments.findActiveLearnerIds(courseId)) {
            notifier.send(learnerId, "A new lesson is available in your course");
        }
        return lesson;
    }
}

