package com.acme.learning.audit;

import java.time.Instant;
import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;

/**
 * Persists an audit entry on each learner progress event.
 */
public class LearningProgressAuditor {

    private final EntityManager em;

    public LearningProgressAuditor(EntityManager em) {
        this.em = em;
    }

    public void record(String learnerId, String entityType, String entityId, String oldState, String newState) {
        EntityTransaction tx = em.getTransaction();
        tx.begin();
        try {
            LearningAuditEntry e = new LearningAuditEntry();
            e.setLearnerId(learnerId);
            e.setEntityType(entityType);
            e.setEntityId(entityId);
            e.setOldState(oldState);
            e.setNewState(newState);
            e.setOccurredAt(Instant.now());
            em.persist(e);
            tx.commit();
        } catch (RuntimeException ex) {
            tx.rollback();
            throw ex;
        }
    }
}

