package com.acme.learning.security;

import org.springframework.security.access.AccessDeniedException;

/**
 * Authorises viewing a learner's progress.
 */
public class ProgressViewPolicy {

    private final CourseRepository courses;
    private final EnrolmentRepository enrolments;

    public ProgressViewPolicy(CourseRepository courses, EnrolmentRepository enrolments) {
        this.courses = courses;
        this.enrolments = enrolments;
    }

    public void assertMayView(String viewerId, String learnerId, String courseId) {
        if (viewerId.equals(learnerId) && enrolments.isEnrolled(learnerId, courseId)) {
            return;
        }
        Course c = courses.require(courseId);
        if (viewerId.equals(c.getInstructorId()) && enrolments.isEnrolled(learnerId, courseId)) {
            return;
        }
        throw new AccessDeniedException("Viewer " + viewerId + " may not view progress for " + learnerId);
    }
}

