/* course_analytics.c - write per-course analytics summary as CSV */
#include <stdio.h>
#include "elearning_db.h"

int write_course_analytics(const char *day, const char *path) {
    FILE *out = fopen(path, "w");
    if (!out) return -1;
    fprintf(out, "course_id,active_learners,avg_completion_pct,certificates_issued\n");

    db_cursor_t *cur = NULL;
    if (db_open_course_analytics_cursor(&cur, day) != DB_OK) { fclose(out); return -2; }

    int rows = 0;
    analytics_row_t row;
    while (db_analytics_cursor_next(cur, &row) == DB_OK) {
        fprintf(out, "%s,%d,%.2f,%d\n",
                row.course_id, row.active_learners, row.avg_completion_pct, row.certs_issued);
        rows++;
    }
    db_close_cursor(cur);
    fclose(out);
    return rows;
}

